import React, { useState } from 'react';
import { Calendar, ChevronDown, AlertCircle, User, MapPin, LayoutGrid, Download, Hash } from 'lucide-react';

const CollectionSchedule = () => {
  const [day, setDay] = useState('22');
  const [month, setMonth] = useState('MARCH');
  const [year, setYear] = useState('2026');
  const [viewMode, setViewMode] = useState('DAY');

  const scheduleLogs = [
    { id: 'SCH-1092', date: '22 MAR', time: '08:45', zone: 'NORTH_SEC', area: 'Hillside Drive', code: 'HSD-44', worker: 'RAVI_KUMAR', bins: '401, 405, 409', report: 'SENSOR_ERR' },
    { id: 'SCH-1104', date: '22 MAR', time: '13:20', zone: 'CENTRAL_HUB', area: 'Main Square', code: 'MSQ-01', worker: 'SITA_MAHESH', bins: '101, 102', report: null },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-4 md:gap-6 font-black italic uppercase tracking-tighter">

      {/* 🛠️ RESPONSIVE HEADER */}
      <div className="flex flex-col xl:flex-row items-stretch xl:items-center gap-4">

        {/* VIEW SWITCHER - Full width on mobile */}
        <div className="flex bg-[#47510B] p-1.5 rounded-2xl border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#A1AED1]">
          <button 
            onClick={() => setViewMode('DAY')}
            className={`flex-1 px-4 md:px-6 py-2.5 rounded-xl flex items-center justify-center gap-2 transition-all text-xs md:text-sm ${viewMode === 'DAY' ? 'bg-[#FFB6A9] text-[#47510B]' : 'text-white/40'}`}
          >
            <Calendar size={16} /> DAY
          </button>
          <button 
            onClick={() => setViewMode('MONTH')}
            className={`flex-1 px-4 md:px-6 py-2.5 rounded-xl flex items-center justify-center gap-2 transition-all text-xs md:text-sm ${viewMode === 'MONTH' ? 'bg-[#A1AED1] text-[#47510B]' : 'text-white/40'}`}
          >
            <LayoutGrid size={16} /> MONTH
          </button>
        </div>

        {/* SELECTORS - Wraps on small screens */}
        <div className="flex flex-wrap bg-[#FFF24D] border-[4px] border-[#47510B] rounded-2xl px-4 py-2 items-center gap-4 md:gap-6 shadow-[4px_4px_0_0_#47510B] justify-between md:justify-start">
          {viewMode === 'DAY' && (
            <div className="relative border-r-2 border-[#47510B]/20 pr-4">
              <select value={day} onChange={(e) => setDay(e.target.value)} className="appearance-none bg-transparent pr-6 text-lg md:text-xl text-[#47510B] outline-none cursor-pointer font-[1000]">
                {[...Array(31)].map((_, i) => <option key={i+1} value={i+1}>{String(i+1).padStart(2, '0')}</option>)}
              </select>
              <ChevronDown className="absolute right-0 top-1 text-[#47510B] pointer-events-none" size={18} />
            </div>
          )}
          <div className="relative border-r-2 border-[#47510B]/20 pr-4">
             <select value={month} onChange={(e) => setMonth(e.target.value)} className="appearance-none bg-transparent pr-6 text-lg md:text-xl text-[#47510B] outline-none cursor-pointer font-[1000]">
                {['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <ChevronDown className="absolute right-0 top-1 text-[#47510B] pointer-events-none" size={18} />
          </div>
          <div className="relative">
             <select value={year} onChange={(e) => setYear(e.target.value)} className="appearance-none bg-transparent pr-6 text-lg md:text-xl text-[#47510B] outline-none cursor-pointer font-[1000]">
                {['2025', '2026', '2027'].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
             <ChevronDown className="absolute right-0 top-1 text-[#47510B] pointer-events-none" size={18} />
          </div>
        </div>
      </div>

      {/* 🌊 DATA DISPLAY: RESPONSIVE CARDS */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-6 pb-10">
        {scheduleLogs.map((log) => (
          <div key={log.id} className="relative group">
            <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-[30px]" />

            <div className="relative bg-white border-[4px] border-[#47510B] rounded-[30px] overflow-hidden flex flex-col md:flex-row transition-all">

              {/* DATE/TIME (Adapts from Side-Strip to Top-Strip) */}
              <div className="bg-[#A1AED1] border-b-[4px] md:border-b-0 md:border-r-[4px] border-[#47510B] p-4 md:p-6 flex flex-row md:flex-col items-center justify-between md:justify-center md:min-w-[140px]">
                <div className="text-left md:text-center">
                  <p className="text-[9px] opacity-60 mb-0.5">{log.date}</p>
                  <h2 className="text-3xl md:text-4xl text-[#47510B] leading-none">{log.time}</h2>
                </div>
                <span className="text-[8px] bg-[#47510B] text-white px-2 py-1 rounded italic mt-0 md:mt-2">ID_{log.id}</span>
              </div>

              {/* LOCATION & DATA PILLS */}
              <div className="flex-grow p-4 md:p-6 flex flex-col gap-4">
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                  <div>
                    <div className="flex items-center gap-1.5 mb-1">
                      <MapPin size={14} className="text-[#AB1717]" />
                      <span className="text-[10px] md:text-xs text-[#AB1717]">{log.zone} // {log.code}</span>
                    </div>
                    <h1 className="text-2xl md:text-4xl text-[#47510B] leading-none truncate">{log.area}</h1>
                  </div>

                  {/* COMPACT PILLS (Grid for responsiveness) */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 md:gap-3">
                    <div className="bg-[#47510B] text-white px-3 py-2 rounded-xl flex items-center gap-3 border-2 border-white shadow-[2px_2px_0_0_#47510B]">
                      <User size={16} className="text-[#FFB6A9]" />
                      <span className="text-[10px] md:text-xs truncate">{log.worker}</span>
                    </div>
                    <div className="bg-[#FFF24D] border-[2px] border-[#47510B] px-3 py-2 rounded-xl flex items-center gap-3 shadow-[2px_2px_0_0_#47510B]">
                      <Hash size={16} className="text-[#47510B]" />
                      <span className="text-[10px] md:text-xs font-mono">{log.bins}</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* REPORT STATUS (Always visible as a side or bottom block) */}
              <div className={`p-4 md:w-28 flex items-center justify-center border-t-[4px] md:border-t-0 md:border-l-[4px] border-[#47510B] ${log.report ? 'bg-[#AB1717] animate-pulse' : 'bg-gray-50'}`}>
                {log.report ? (
                  <div className="flex flex-row md:flex-col items-center gap-2 text-white">
                    <AlertCircle size={24} />
                    <span className="text-[8px] font-black md:hidden uppercase">Incident Reported</span>
                  </div>
                ) : (
                  <div className="w-2 h-2 rounded-full bg-[#CAD23C]" />
                )}
              </div>

            </div>
          </div>
        ))}
      </div>

      {/* 🧭 MINIMALIST FOOTER ACTION BAR */}
      <div className="bg-[#47510B] p-3 md:p-4 rounded-full flex flex-col md:flex-row justify-between items-center border-[3px] border-white shadow-[6px_6px_0_0_#A1AED1] gap-3">
         <p className="text-white text-sm md:text-lg ml-0 md:ml-6 italic text-center md:text-left">
            VIEWING: <span className="text-[#FFB6A9]">{viewMode === 'DAY' ? `${day} ${month}` : `MANIFEST_${month}`}</span>
         </p>
         <button className="w-full md:w-auto bg-[#FFF24D] text-[#47510B] px-8 py-2 md:py-2.5 rounded-full text-xs font-[1000] border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#47510B] flex items-center justify-center gap-2 active:shadow-none transition-all">
            <Download size={16} /> EXPORT_CSV
         </button>
      </div>

    </div>
  );
};

export default CollectionSchedule;
